function deepGet(obj, keys) {
  if (!obj || typeof obj !== 'object') return undefined;
  for (const k of Object.keys(obj)) {
    const kk = k.toLowerCase();
    for (const target of keys) {
      if (kk === target || kk.includes(target)) {
        const v = obj[k];
        if (v == null) continue;
        if (Array.isArray(v)) return String(v[0] ?? '').trim();
        if (typeof v === 'object') {
          const inner = v.values?.[0] ?? v.value ?? v.text ?? v.label;
          if (inner != null) return String(inner).trim();
          continue;
        }
        if (typeof v === 'string' || typeof v === 'number') return String(v).trim();
      }
    }
    if (obj[k] && typeof obj[k] === 'object') {
      const r = deepGet(obj[k], keys);
      if (r !== undefined) return r;
    }
  }
  return undefined;
}

function findSource(obj) {
  if (!obj || typeof obj !== 'object') return undefined;
  for (const k of Object.keys(obj)) {
    if (k.toLowerCase() === 'source' && typeof obj[k] === 'string') return obj[k].trim().toLowerCase();
    if (obj[k] && typeof obj[k] === 'object') {
      const r = findSource(obj[k]);
      if (r) return r;
    }
  }
  return undefined;
}

const first = deepGet($json, ['first_name', 'fname']) || '';
const last = deepGet($json, ['last_name', 'lname']) || '';
const raw = JSON.stringify($json).toLowerCase();
const name = deepGet($json, ['full_name']) || `${first} ${last}`.trim() || deepGet($json, ['name', 'contact_name']) || 'Unknown';
const email = (deepGet($json, ['email', 'email_address', 'e-mail', 'mail']) || '').toLowerCase();
const phone = deepGet($json, ['phone', 'phone_number', 'mobile', 'whatsapp', 'telephone', 'contact_number', 'customer_phone']) || '';

let source = findSource($json) || 'manual';
if (source === 'manual' && (raw.includes('leadgen') || raw.includes('field_data'))) source = 'meta';
else if (source === 'manual' && raw.includes('answers') && (raw.includes('fieldlabel') || raw.includes('field_key'))) source = 'linkedin';
else if (source === 'manual' && raw.includes('from') && raw.includes('whatsapp')) source = 'whatsapp';

const params = [];
if (email) params.push(`email=eq.${encodeURIComponent(email)}`);
if (phone) params.push(`phone=eq.${encodeURIComponent(phone)}`);
const filter = params.length === 1 ? params[0] : `or=(${params.join(',')})`;
const checkUrl = params.length
  ? `${$env.SUPABASE_URL}/rest/v1/leads?${filter}&select=id`
  : '';

return [{ json: { name, email, phone, source, raw_data: $json, checkUrl } }];
